const result = $json["tasks"][0]["result"][0];
const output = [];

if (result.items) {
  for (const item of result.items) {
    if (item.type === 'organic') {
      output.push({
        json: {
          Keyword: result.keyword,
          Rank: item.rank_group,
          Position: item.rank_absolute,
          Title: item.title || '',
          URL: item.url || '',
          Domain: item.domain || '',
          Breadcrumb: item.breadcrumb || '',
          Snippet: item.description || ''
        }
      });
    }
  }
}

return output;

const keywords = $json.Keyword || [];

// Clean array
const cleanedKeywords = keywords
  .filter(k => k && k.trim() !== "")   // remove empty / null
  .map(k => k.trim());                 // remove extra spaces

return [
  {
    json: {
      Keyword: cleanedKeywords
    }
  }
];

const results = $json.tasks?.[0]?.result || [];

const cleaned = results.map(item => ({
  keyword: item.keyword,

  search_volume: item.search_volume ?? 0,

  competition: item.competition ?? "N/A",

  competition_index: item.competition_index ?? 0,

  cpc: item.cpc ?? 0
}));

return cleaned.map(r => ({ json: r }));

const paragraphs = $json.p || [];

let cleaned = paragraphs
  .map(p => p.trim())
  .filter(p => {
    const wordCount = p.split(/\s+/).length;
    return wordCount >= 12;
  });

// Remove duplicates
cleaned = [...new Set(cleaned)];

const MAX_TOKENS = 2000;
let totalTokens = 0;

const selected = [];

for (const p of cleaned) {
  const wordCount = p.split(/\s+/).length;

  // Approximate tokens
  const estimatedTokens = Math.ceil(wordCount / 0.75);

  if (totalTokens + estimatedTokens > MAX_TOKENS) {
    break;
  }

  selected.push(p);
  totalTokens += estimatedTokens;
}

return [
  {
    json: {
      paragraphs: selected,
      estimated_tokens: totalTokens
    }
  }
];

const data = $input.all().map(item => item.json);

// Normalize helper
function normalize(str) {
  return str.toLowerCase().replace(/[^a-z0-9\s]/g, "").trim();
}

// Check similarity (simple semantic match)
function isSimilar(a, b) {
  return a.includes(b) || b.includes(a);
}

// Group keywords
const groups = [];

for (const item of data) {
  const keyword = item["Keyword"];
  const norm = normalize(keyword);

  let added = false;

  for (const group of groups) {
    if (isSimilar(norm, group.norm)) {
      group.items.push(item);
      added = true;
      break;
    }
  }

  if (!added) {
    groups.push({
      norm,
      items: [item]
    });
  }
}

// Select best from each group
const selected = groups.map(group => {
  return group.items.sort((a, b) => {
    const svA = a["Search Volume "] || 0;
    const svB = b["Search Volume "] || 0;

    const cpcA = a["CPC "] || 0;
    const cpcB = b["CPC "] || 0;

    // Sort by Search Volume → then CPC
    return (svB - svA) || (cpcB - cpcA);
  })[0];
});

return selected.map(k => ({ json: k }));

const items = $json.tasks?.[0]?.result?.[0]?.items || [];

const cleaned = items.map(item => ({
  keyword: item.keyword,
  kd: item.keyword_difficulty ?? 0
}));

return cleaned.map(k => ({ json: k }));

