const tasks = $json.tasks || [];
const items = tasks[0]?.result?.[0]?.items || [];

function safe(value) {
  return value ?? null;
}

function calculateOpportunity(info, props, trend) {
  const volume = info.search_volume || 0;
  const difficulty = props.keyword_difficulty || 1;
  const growth = trend.monthly || 0;

  // You can adjust formula later
  return Math.round((volume * (growth + 100)) / (difficulty + 1));
}

const cleaned = items.map(item => {

  const info = item.keyword_info || {};
  const trend = info.search_volume_trend || {};
  const props = item.keyword_properties || {};
  const backlinks = item.avg_backlinks_info || {};
  const intent = item.search_intent_info || {};

  return {
    keyword: safe(item.keyword),
    location_code: safe(item.location_code),
    language_code: safe(item.language_code),

    search_volume: safe(info.search_volume),
    competition: safe(info.competition),
    competition_level: safe(info.competition_level),
    cpc: safe(info.cpc),
    low_top_of_page_bid: safe(info.low_top_of_page_bid),
    high_top_of_page_bid: safe(info.high_top_of_page_bid),

    trend_monthly: safe(trend.monthly),
    trend_quarterly: safe(trend.quarterly),
    trend_yearly: safe(trend.yearly),

    keyword_difficulty: safe(props.keyword_difficulty),
    words_count: safe(props.words_count),
    core_keyword: safe(props.core_keyword),

    intent: safe(intent.main_intent),

    backlinks_avg: safe(backlinks.backlinks),
    referring_pages_avg: safe(backlinks.referring_pages),
    referring_domains_avg: safe(backlinks.referring_domains),
    referring_main_domains_avg: safe(backlinks.referring_main_domains),
    main_domain_rank_avg: safe(backlinks.main_domain_rank),
    serp_rank_avg: safe(backlinks.rank),

    last_updated: safe(info.last_updated_time),

    opportunity_score: calculateOpportunity(info, props, trend)
  };
});

return cleaned.map(row => ({ json: row }));

// Get primary keyword from form submission node
const primaryKeyword = $('If').first().json.output.primary_keyword;

// Get original full dataset
const originalItems = $items("OriginalData1");

// Get filtered keyword dataset
const filteredItems = $items("FilteredKeywords1");

// Create lookup map from filtered keywords
const intentMap = new Map(
  filteredItems.map(item => [
    item.json.keyword,
    {
      intent: item.json.intent,
      probability: item.json.probability
    }
  ])
);

// Merge everything
const merged = originalItems
  .filter(item => intentMap.has(item.json.keyword))
  .map(item => ({
    json: {
      primary_keyword: primaryKeyword,
      ...item.json,
      ...intentMap.get(item.json.keyword)
    }
  }));

return merged;

const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json,
    total_keywords: items.length
  }
}));

