const input = $input.all();
const output = [];

for (const item of input) {

  const block =
    item.json?.tasks?.[0]?.result?.[0]?.items?.[0];

  // 🚨 SAFETY CHECK
  if (!block || !block.data || !block.keywords) {
    continue; // skip broken entries
  }

  const keywords = block.keywords;
  const timeline = block.data;

  // 🚨 another safety
  if (!Array.isArray(timeline) || timeline.length === 0) {
    continue;
  }

  const sums = new Array(keywords.length).fill(0);
  const hasValue = new Array(keywords.length).fill(false);

  const totalPoints = timeline.length;

  for (const row of timeline) {

    const values = row?.values;

    if (!values) continue;

    for (let i = 0; i < values.length; i++) {

      const v = values[i];

      if (v !== null) {
        sums[i] += v;
        if (v > 0) hasValue[i] = true;
      }

    }
  }

  for (let i = 0; i < keywords.length; i++) {

    let avg = sums[i] / totalPoints;

    avg = Math.round(avg);

    if (avg === 0 && hasValue[i]) {
      avg = 1;
    }

    output.push({
      json: {
        keyword: keywords[i],
        average: avg
      }
    });

  }

}

return output;

